import{_ as s,o,c as a,a2 as t}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Invoking-pspp_002ddump_002dsav.md","filePath":"manual-en/Invoking-pspp_002ddump_002dsav.md","lastUpdated":1785684581000}'),p={name:"manual-en/Invoking-pspp_002ddump_002dsav.md"};function n(d,e,i,r,c,m){return o(),a("div",null,[...e[0]||(e[0]=[t(`<h2 id="_20-invoking-pspp-dump-sav" tabindex="-1">20 Invoking <code>pspp-dump-sav</code> <a class="header-anchor" href="#_20-invoking-pspp-dump-sav" aria-label="Permalink to &quot;20 Invoking \`pspp-dump-sav\`&quot;">​</a></h2><p><code>pspp-dump-sav</code> is a command-line utility accompanying PSPP. It is not installed by default, so it may be missing from your PSPP installation. It reads one or more SPSS system files and prints their contents. The output format is useful for debugging system file readers and writers and for discovering how to interpret unknown or poorly understood records. End users may find the output useful for providing the PSPP developers information about system files that PSPP does not accurately read.</p><p>Synopsis:</p><pre><code>pspp-dump-sav [-d[maxcases] | --data[=maxcases]] file…

pspp-dump-sav --help | -h

pspp-dump-sav --version | -v
</code></pre><p>The following options are accepted:</p><p><code>-d</code>[maxcases] <code>--data</code>[<code>=</code>maxcases]</p><p>By default, <code>pspp-dump-sav</code> does not print any of the data in a system file, only the file headers. Specify this option to print the data as well. If maxcases is specified, then it limits the number of cases printed.</p><p><code>-h</code><code>--help</code></p><p>Prints a usage message on stdout and exits.</p><p><code>-v</code><code>--version</code></p><p>Prints version information on stdout and exits.</p><p>Some errors that prevent files from being interpreted successfully cause <code>pspp-dump-sav</code> to exit without reading any additional files given on the command line.</p>`,12)])])}const f=s(p,[["render",n]]);export{u as __pageData,f as default};
